using System;
using System.Collections.Generic;
using Synthetic;
using Synthetic.Euclidean;

namespace Viz.Adapters.Synthetic
{

    public interface IVizDatasetAdapter<TSource>
    {
        VizDataset Adapt(TSource source);
    }

    public sealed class SyntheticDatasetAdapter : IVizDatasetAdapter<SyntheticDataset>
    {
        public VizDataset Adapt(SyntheticDataset source)
        {
            if (source is null) throw new ArgumentNullException(nameof(source));
            if (source.Features is null || source.Features.Length == 0)
                throw new ArgumentException("SyntheticDataset has no features.", nameof(source));

            int n = source.Features.Length;
            int d = source.Features[0].Length;

            for (int i = 1; i < n; i++)
                if (source.Features[i].Length != d)
                    throw new ArgumentException(
                        $"Feature row {i} has dimension {source.Features[i].Length}, expected {d}.");

            var flat = new double[n * d];
            for (int i = 0; i < n; i++)
                source.Features[i].CopyTo(flat, i * d);

            var cloud = new PointCloud(
                flat, n, d,
                label: BuildCloudLabel(source));

            var gtLayer = new LabelLayer(
                "Ground Truth",
                (int[])source.Labels.Clone(),
                LabelLayerKind.GroundTruth,
                id: "ground-truth");

            List<SpineLayer> spineLayers = BuildSpineLayers(source);

            string? generatorName = source.Parameters.TryGetValue("generator", out var gn)
                ? gn?.ToString()
                : null;

            return new VizDataset(
                points: cloud,
                labelLayers: new List<LabelLayer> { gtLayer },
                nodeSignalLayers: Array.Empty<NodeSignalLayer>(),
                edgeLayers: Array.Empty<EdgeLayer>(),
                gaussianLayers: Array.Empty<GaussianLayer>(),
                temporalSequences: Array.Empty<TemporalLabelSequence>(),
                spineLayers: spineLayers,
                triangleLayers: Array.Empty<TriangleLayer>(),
                generatorParams: source.Parameters.Count > 0
                    ? source.Parameters
                    : null,
                generatorParamSchema: SchemaCatalog.ForGenerator(generatorName));
        }

        private static string BuildCloudLabel(SyntheticDataset source)
        {
            int n = source.Features.Length;
            int d = source.Features[0].Length;
            string genName = source.Parameters.TryGetValue("generator", out var g)
                ? g?.ToString() ?? "Synthetic"
                : "Synthetic";
            return $"{genName} (N={n}, D={d}, K={source.ClusterCount})";
        }

        private static List<SpineLayer> BuildSpineLayers(SyntheticDataset source)
        {
            var result = new List<SpineLayer>();
            if (source.ClusterGeometries is null) return result;

            for (int i = 0; i < source.ClusterGeometries.Length; i++)
            {
                switch (source.ClusterGeometries[i])
                {
                    case ArcGeometry arc:
                        result.Add(new SpineLayer(
                            name: $"Cluster {i} Arc Spine",
                            clusterIdx: i,
                            kind: SpineLayerKind.Arc,
                            spineSamples: arc.SpineSamples,
                            tangentBases: null,
                            typicalScale: arc.NoiseScale,
                            id: $"cluster-{i}-arc-spine"));
                        break;

                    case ManifoldGeometry mf:
                        result.Add(new SpineLayer(
                            name: $"Cluster {i} Manifold Spine",
                            clusterIdx: i,
                            kind: SpineLayerKind.Manifold,
                            spineSamples: mf.SpineSamples,
                            tangentBases: mf.TangentBases,
                            typicalScale: 0.0,
                            id: $"cluster-{i}-manifold-spine"));
                        break;

                    case MobiusTubeGeometry mob:

                        result.Add(new SpineLayer(
                            name: $"Cluster {i} Möbius Spine",
                            clusterIdx: i,
                            kind: SpineLayerKind.MobiusTube,
                            spineSamples: mob.SpineSamples,
                            tangentBases: mob.LocalFrames,
                            typicalScale: Math.Sqrt(mob.HalfWidth * mob.HalfThickness),
                            id: $"cluster-{i}-mobius-spine"));
                        break;

                    default:
                        break;
                }
            }

            return result;
        }
    }
}

using System;
using Clustering.Statistical.GMM;

namespace Viz.Adapters.Gmm
{
    public static class GmmVizAdapter
    {

        public static GaussianLayer ToGaussianLayer(
            GaussianMixtureModel gmm,
            string name = "Fitted GMM",
            IComponentMergeStrategy? mergeStrategy = null)
        {
            int k = gmm.K;
            int d = gmm.Dimension;
            var means = new double[k * d];
            var covariances = new double[k * d * d];
            var weights = new double[k];

            for (int ki = 0; ki < k; ki++)
            {
                var comp = gmm.Components[ki];
                weights[ki] = comp.Weight;
                for (int dim = 0; dim < d; dim++)
                    means[ki * d + dim] = comp.Mean[dim];
                for (int row = 0; row < d; row++)
                    for (int col = 0; col < d; col++)
                        covariances[ki * d * d + row * d + col] = comp.Covariance[row, col];
            }

            int[]? componentToClusterMap = mergeStrategy?.Merge(
                gmm.Components, gmm.GetFinalResponsibilities());

            return new GaussianLayer(name, means, covariances, weights, k, d, componentToClusterMap);
        }

        public static LabelLayer ToComponentLabels(
            GaussianMixtureModel gmm, double[][] data,
            string name = "GMM Component")
        {
            return new LabelLayer(name, gmm.Predict(data), LabelLayerKind.GmmComponent);
        }

        public static LabelLayer ToClusterLabels(
            GaussianMixtureModel gmm, double[][] data,
            IComponentMergeStrategy strategy,
            string name = "GMM Cluster")
        {
            int[] componentLabels = gmm.Predict(data);
            int[] map = strategy.Merge(gmm.Components, gmm.GetFinalResponsibilities());
            int n = componentLabels.Length;
            var clusterLabels = new int[n];
            for (int i = 0; i < n; i++)
                clusterLabels[i] = map[componentLabels[i]];
            return new LabelLayer(name, clusterLabels, LabelLayerKind.GmmCluster);
        }

        public static NodeSignalLayer ToResponsibilityScalar(
            GaussianMixtureModel gmm, int k, string? name = null)
        {
            double[,] r = gmm.GetFinalResponsibilities()
                ?? throw new InvalidOperationException(
                    "GMM has no cached responsibilities; call Fit first.");
            int n = r.GetLength(0);
            var values = new double[n];
            for (int i = 0; i < n; i++)
                values[i] = r[i, k];
            return new NodeSignalLayer(
                name ?? $"Responsibility (k={k})", values, ScalarSource.Responsibility);
        }

        public static NodeSignalLayer ToMahalanobisScalar(
            GaussianMixtureModel gmm, double[][] data,
            string name = "Mahalanobis (min over k)")
        {
            double[,] mahal = gmm.Mahal(data);
            int n = data.Length;
            int kCount = gmm.K;
            var values = new double[n];
            for (int i = 0; i < n; i++)
            {
                double minSq = double.MaxValue;
                for (int ki = 0; ki < kCount; ki++)
                {
                    double v = mahal[i, ki];
                    if (v < minSq) minSq = v;
                }
                values[i] = Math.Sqrt(minSq);
            }
            return new NodeSignalLayer(name, values, ScalarSource.MahalanobisDistance);
        }
    }
}

using System;
using System.IO;
using System.Reflection;
using System.Text;
using Viz;

namespace Viz.Renderers
{

    public sealed class ThreeJsHtmlRenderTarget : IRenderTarget
    {
        private static readonly JsonExportRenderTarget _json = new(compact: true);
        private static readonly string _template = LoadTemplate();

        private static string LoadTemplate()
        {
            var asm = Assembly.GetExecutingAssembly();
            using var stream = asm.GetManifestResourceStream("Viz.viewer.html")
                ?? throw new InvalidOperationException(
                    "Embedded resource 'Viz.viewer.html' not found. " +
                    "Ensure viewer.html is marked EmbeddedResource in VizCore.csproj.");
            using var reader = new StreamReader(stream, Encoding.UTF8);
            return reader.ReadToEnd();
        }

        public void Render(ScenePackage scene, Stream output)
        {
            if (scene is null) throw new ArgumentNullException(nameof(scene));
            if (output is null) throw new ArgumentNullException(nameof(output));

            using var jsonStream = new MemoryStream();
            _json.Render(scene, jsonStream);
            string json = Encoding.UTF8.GetString(jsonStream.ToArray());

            string html = _template.Replace("__SCENE_DATA__", json);
            byte[] bytes = Encoding.UTF8.GetBytes(html);
            output.Write(bytes, 0, bytes.Length);
        }
    }
}

using System;
using System.Buffers;
using Maths.Geometry;

namespace Viz
{
    public static class LocalTangent
    {

        public const int DefaultMinNeighbors = 2;

        public const int DefaultPowerIterations = 20;

        public static double[] Compute(
            double[][] points,
            int[][] adjacency,
            int minNeighbors = DefaultMinNeighbors,
            int powerIterations = DefaultPowerIterations)
        {
            return Compute(
                points,
                adjacency,
                manifold: null,
                minNeighbors: minNeighbors,
                powerIterations: powerIterations);
        }

        public static double[] Compute(
            double[][] points,
            int[][] adjacency,
            IRiemannianManifold? manifold,
            int minNeighbors = DefaultMinNeighbors,
            int powerIterations = DefaultPowerIterations)
        {
            if (points is null) throw new ArgumentNullException(nameof(points));
            if (adjacency is null) throw new ArgumentNullException(nameof(adjacency));
            if (points.Length != adjacency.Length)
                throw new ArgumentException(
                    "points and adjacency must have the same length.", nameof(adjacency));

            int n = points.Length;
            if (n == 0) return Array.Empty<double>();

            int d = points[0].Length;
            if (manifold is not null && manifold.Dimension != d)
                throw new ArgumentException(
                    "manifold.Dimension must match the point dimension.", nameof(manifold));

            var result = new double[n * d];
            bool useEuclideanPath = manifold is null || manifold is EuclideanVectorManifold;

            double[] meanBuf = ArrayPool<double>.Shared.Rent(d);
            double[] scatterBuf = ArrayPool<double>.Shared.Rent(d * d);
            double[] vecBuf = ArrayPool<double>.Shared.Rent(d);
            double[] nextBuf = ArrayPool<double>.Shared.Rent(d);
            double[] tangentBuf = ArrayPool<double>.Shared.Rent(d);
            double[] workBuf = ArrayPool<double>.Shared.Rent(d);

            try
            {
                Span<double> mean = meanBuf.AsSpan(0, d);
                Span<double> scatter = scatterBuf.AsSpan(0, d * d);
                Span<double> vec = vecBuf.AsSpan(0, d);
                Span<double> next = nextBuf.AsSpan(0, d);
                Span<double> tangent = tangentBuf.AsSpan(0, d);
                Span<double> work = workBuf.AsSpan(0, d);

                for (int i = 0; i < n; i++)
                {
                    int[] nbrs = adjacency[i];
                    if (nbrs is null || nbrs.Length < minNeighbors) continue;
                    int k = nbrs.Length;

                    scatter.Clear();

                    if (useEuclideanPath)
                    {
                        mean.Clear();
                        for (int j = 0; j < k; j++)
                        {
                            double[] q = points[nbrs[j]];
                            for (int dim = 0; dim < d; dim++)
                                mean[dim] += q[dim];
                        }

                        double invK = 1.0 / k;
                        for (int dim = 0; dim < d; dim++) mean[dim] *= invK;

                        for (int j = 0; j < k; j++)
                        {
                            double[] q = points[nbrs[j]];
                            for (int r = 0; r < d; r++)
                            {
                                double vr = q[r] - mean[r];
                                for (int c = 0; c < d; c++)
                                    scatter[r * d + c] += vr * (q[c] - mean[c]);
                            }
                        }
                    }
                    else
                    {
                        ComputeKarcherMean(points, nbrs, manifold!, mean, tangent, work);

                        for (int j = 0; j < k; j++)
                        {
                            manifold!.LogMap(mean, points[nbrs[j]], tangent);
                            for (int r = 0; r < d; r++)
                            {
                                double vr = tangent[r];
                                for (int c = 0; c < d; c++)
                                    scatter[r * d + c] += vr * tangent[c];
                            }
                        }
                    }

                    vec.Clear();
                    vec[0] = 1.0;

                    for (int iter = 0; iter < powerIterations; iter++)
                    {
                        next.Clear();
                        for (int r = 0; r < d; r++)
                            for (int c = 0; c < d; c++)
                                next[r] += scatter[r * d + c] * vec[c];

                        double norm = 0;
                        for (int dim = 0; dim < d; dim++) norm += next[dim] * next[dim];
                        norm = Math.Sqrt(norm);

                        if (norm < 1e-12) goto zeroed; // degenerate neighbourhood

                        double invNorm = 1.0 / norm;
                        for (int dim = 0; dim < d; dim++) vec[dim] = next[dim] * invNorm;
                    }

                    int offset = i * d;
                    for (int dim = 0; dim < d; dim++) result[offset + dim] = vec[dim];
                    continue;

                zeroed:; // tangent stays zero for this point
                }
            }
            finally
            {
                ArrayPool<double>.Shared.Return(meanBuf);
                ArrayPool<double>.Shared.Return(scatterBuf);
                ArrayPool<double>.Shared.Return(vecBuf);
                ArrayPool<double>.Shared.Return(nextBuf);
                ArrayPool<double>.Shared.Return(tangentBuf);
                ArrayPool<double>.Shared.Return(workBuf);
            }

            return result;
        }

        private static void ComputeKarcherMean(
            double[][] points,
            int[] neighbors,
            IRiemannianManifold manifold,
            Span<double> mean,
            Span<double> tangent,
            Span<double> work)
        {
            points[neighbors[0]].AsSpan().CopyTo(mean);
            double invCount = 1.0 / neighbors.Length;

            for (int iteration = 0; iteration < 16; iteration++)
            {
                work.Clear();

                for (int j = 0; j < neighbors.Length; j++)
                {
                    manifold.LogMap(mean, points[neighbors[j]], tangent);
                    for (int dim = 0; dim < mean.Length; dim++)
                        work[dim] += tangent[dim];
                }

                for (int dim = 0; dim < mean.Length; dim++)
                    work[dim] *= invCount;

                if (manifold.Norm(mean, work) < 1e-8)
                    return;

                manifold.ExpMap(mean, work, tangent);
                tangent.CopyTo(mean);
            }
        }

        public static void PropagateOrientation(
            double[] tangents, int n, int d,
            int[] rowPointers, int[] targets)
        {
            if (n == 0 || d == 0) return;

            bool[] visited = new bool[n];
            int[] queue = new int[n];

            for (int seed = 0; seed < n; seed++)
            {
                if (visited[seed]) continue;

                int seedOff = seed * d;
                bool hasNonZero = false;
                for (int dim = 0; dim < d; dim++)
                    if (tangents[seedOff + dim] != 0.0) { hasNonZero = true; break; }
                if (!hasNonZero) { visited[seed] = true; continue; }

                int head = 0, tail = 0;
                queue[tail++] = seed;
                visited[seed] = true;

                while (head < tail)
                {
                    int i = queue[head++];
                    int iOff = i * d;
                    int rowStart = rowPointers[i];
                    int rowEnd = rowPointers[i + 1];

                    for (int idx = rowStart; idx < rowEnd; idx++)
                    {
                        int j = targets[idx];
                        if (visited[j]) continue;
                        visited[j] = true;

                        int jOff = j * d;
                        double dot = 0.0;
                        for (int dim = 0; dim < d; dim++)
                            dot += tangents[iOff + dim] * tangents[jOff + dim];
                        if (dot < 0.0)
                            for (int dim = 0; dim < d; dim++)
                                tangents[jOff + dim] = -tangents[jOff + dim];

                        queue[tail++] = j;
                    }
                }
            }
        }

        public static double[] ComputeCoherence(
            double[] tangents, int n, int d,
            int[] rowPointers, int[] targets)
        {
            var coherence = new double[n];

            for (int i = 0; i < n; i++)
            {
                int rowStart = rowPointers[i];
                int rowEnd = rowPointers[i + 1];
                int degree = rowEnd - rowStart;
                if (degree == 0) continue;

                int iOff = i * d;
                double sum = 0.0;
                for (int idx = rowStart; idx < rowEnd; idx++)
                {
                    int jOff = targets[idx] * d;
                    double dot = 0.0;
                    for (int dim = 0; dim < d; dim++)
                        dot += tangents[iOff + dim] * tangents[jOff + dim];
                    sum += dot;
                }
                coherence[i] = sum / degree;
            }

            return coherence;
        }
    }
}

using System.Text.Json.Serialization;

namespace Viz
{

    public sealed class ParamSpec
    {

        [JsonPropertyName("key")] public string Key { get; init; } = "";

        [JsonPropertyName("label")] public string Label { get; init; } = "";

        [JsonPropertyName("type")] public string Type { get; init; } = "float";
        [JsonPropertyName("min")] public double? Min { get; init; }
        [JsonPropertyName("max")] public double? Max { get; init; }
        [JsonPropertyName("step")] public double? Step { get; init; }
        [JsonPropertyName("enum_values")] public string[]? EnumValues { get; init; }

        [JsonPropertyName("vec_labels")] public string[]? VecLabels { get; init; }

        [JsonPropertyName("display_values")] public string[]? DisplayValues { get; init; }

        [JsonPropertyName("description")] public string? Description { get; init; }
    }

    public sealed class ParamSection
    {
        [JsonPropertyName("label")] public string Label { get; init; } = "";
        [JsonPropertyName("params")] public ParamSpec[] Params { get; init; } = [];
    }

    public sealed class GeneratorParamSchema
    {
        [JsonPropertyName("sections")] public ParamSection[] Sections { get; init; } = [];
    }
}

using System;
using System.Collections.Generic;
using System.IO;

namespace Viz
{

    public sealed class SceneDescriptor
    {
        public string Title { get; init; } = "";
        public string? Description { get; init; }

        public IReadOnlyList<string>? ActiveLabelLayers { get; init; }
        public IReadOnlyList<string>? ActiveNodeSignalLayers { get; init; }
        public IReadOnlyList<string>? ActiveEdgeLayers { get; init; }
        public IReadOnlyList<string>? ActiveTriangleLayers { get; init; }
        public IReadOnlyList<string>? ActiveGaussianLayers { get; init; }
        public IReadOnlyList<string>? ActiveSpineLayers { get; init; }
        public IReadOnlyList<string>? ActiveVectorFieldLayers { get; init; }
        public IReadOnlyList<string>? ActiveLineFieldLayers { get; init; }
        public string? ActiveTemporalSequence { get; init; }
        public int TemporalStartIndex { get; init; } = 0;

        public SceneRenderHints Hints { get; init; } = SceneRenderHints.Default;
    }

    public sealed class SceneRenderHints
    {
        public static readonly SceneRenderHints Default = new();

        public bool ShowEdgeWeightsAsOpacity { get; init; } = true;
        public bool ShowGaussianEllipsoids { get; init; } = false;
        public bool ShowSpineOverlays { get; init; } = true;
        public bool ShowTangentBases { get; init; } = false;

        public bool OverlayComponentAndClusterColoring { get; init; } = false;
        public bool AnnotateSpinColorVsEquilibrium { get; init; } = true;

        public bool HighlightFalseBridges { get; init; } = true;
        public bool ShowVectorField { get; init; } = false;
    }

    public sealed class ScenePackage
    {
        public string Title { get; }
        public PointCloud Points { get; }
        public IReadOnlyList<LabelLayer> ActiveLabelLayers { get; }
        public IReadOnlyList<NodeSignalLayer> ActiveNodeSignalLayers { get; }
        public IReadOnlyList<EdgeLayer> ActiveEdgeLayers { get; }
        public IReadOnlyList<TriangleLayer> ActiveTriangleLayers { get; }
        public IReadOnlyList<GaussianLayer> ActiveGaussianLayers { get; }
        public IReadOnlyList<SpineLayer> ActiveSpineLayers { get; }
        public IReadOnlyList<VectorFieldLayer> ActiveVectorFieldLayers { get; }
        public IReadOnlyList<LineFieldLayer> ActiveLineFieldLayers { get; }
        public TemporalLabelSequence? ActiveSequence { get; }
        public int TemporalFrameIndex { get; }
        public SceneRenderHints Hints { get; }
        public IReadOnlyDictionary<string, object>? GeneratorParams { get; }
        public GeneratorParamSchema? GeneratorParamSchema { get; }

        public ScenePackage(
            PointCloud points,
            IReadOnlyList<LabelLayer> activeLabelLayers,
            IReadOnlyList<NodeSignalLayer> activeNodeSignalLayers,
            IReadOnlyList<EdgeLayer> activeEdgeLayers,
            IReadOnlyList<TriangleLayer> activeTriangleLayers,
            IReadOnlyList<GaussianLayer> activeGaussianLayers,
            IReadOnlyList<SpineLayer> activeSpineLayers,
            TemporalLabelSequence? activeSequence,
            int temporalFrameIndex,
            SceneRenderHints hints,
            IReadOnlyDictionary<string, object>? generatorParams = null,
            GeneratorParamSchema? generatorParamSchema = null,
            IReadOnlyList<VectorFieldLayer>? activeVectorFieldLayers = null,
            IReadOnlyList<LineFieldLayer>? activeLineFieldLayers = null,
            string title = "")
        {
            Title = title;
            Points = points;
            ActiveLabelLayers = activeLabelLayers;
            ActiveNodeSignalLayers = activeNodeSignalLayers;
            ActiveEdgeLayers = activeEdgeLayers;
            ActiveTriangleLayers = activeTriangleLayers;
            ActiveGaussianLayers = activeGaussianLayers;
            ActiveSpineLayers = activeSpineLayers;
            ActiveSequence = activeSequence;
            TemporalFrameIndex = temporalFrameIndex;
            Hints = hints;
            GeneratorParams = generatorParams;
            GeneratorParamSchema = generatorParamSchema;
            ActiveVectorFieldLayers = activeVectorFieldLayers ?? Array.Empty<VectorFieldLayer>();
            ActiveLineFieldLayers = activeLineFieldLayers ?? Array.Empty<LineFieldLayer>();
        }
    }

    public static class SceneBuilder
    {
        public static ScenePackage Build(VizDataset dataset, SceneDescriptor descriptor)
        {
            if (dataset is null) throw new ArgumentNullException(nameof(dataset));
            if (descriptor is null) throw new ArgumentNullException(nameof(descriptor));

            var labelLayers = Filter(dataset.LabelLayers, descriptor.ActiveLabelLayers);
            var nodeSignalLayers = Filter(dataset.NodeSignalLayers, descriptor.ActiveNodeSignalLayers);
            var edgeLayers = Filter(dataset.EdgeLayers, descriptor.ActiveEdgeLayers);
            var triangleLayers = Filter(dataset.TriangleLayers, descriptor.ActiveTriangleLayers);
            var gaussianLayers = Filter(dataset.GaussianLayers, descriptor.ActiveGaussianLayers);
            var spineLayers = Filter(dataset.SpineLayers, descriptor.ActiveSpineLayers);
            var vectorFieldLayers = Filter(dataset.VectorFieldLayers, descriptor.ActiveVectorFieldLayers);
            var lineFieldLayers = Filter(dataset.LineFieldLayers, descriptor.ActiveLineFieldLayers);

            TemporalLabelSequence? activeSeq = null;
            if (descriptor.ActiveTemporalSequence is not null)
            {
                foreach (var seq in dataset.TemporalSequences)
                    if (seq.Name == descriptor.ActiveTemporalSequence) { activeSeq = seq; break; }
            }

            int frameIndex = activeSeq is not null
                ? Math.Clamp(descriptor.TemporalStartIndex, 0, activeSeq.Frames.Count - 1)
                : 0;

            return new ScenePackage(
                points: dataset.Points,
                activeLabelLayers: labelLayers,
                activeNodeSignalLayers: nodeSignalLayers,
                activeEdgeLayers: edgeLayers,
                activeTriangleLayers: triangleLayers,
                activeGaussianLayers: gaussianLayers,
                activeSpineLayers: spineLayers,
                activeSequence: activeSeq,
                temporalFrameIndex: frameIndex,
                hints: descriptor.Hints,
                generatorParams: dataset.GeneratorParams,
                generatorParamSchema: dataset.GeneratorParamSchema,
                activeVectorFieldLayers: vectorFieldLayers,
                activeLineFieldLayers: lineFieldLayers,
                title: descriptor.Title);
        }

        private static IReadOnlyList<T> Filter<T>(
            IReadOnlyList<T> all,
            IReadOnlyList<string>? activeNames) where T : INamedLayer
        {
            if (activeNames is null) return all;

            var nameSet = new HashSet<string>(activeNames, StringComparer.Ordinal);
            var result = new List<T>(activeNames.Count);
            foreach (var item in all)
            {
                if (nameSet.Contains(item.Name))
                    result.Add(item);
            }
            return result;
        }
    }

    public interface IRenderTarget
    {
        void Render(ScenePackage scene, Stream output);
    }
}

namespace Viz
{

    public static class SchemaCatalog
    {

        public static readonly string[] KnownGenerators =
        [
            "CrescentAndEllipsoid",
            "MobiusAndEllipsoid",
            "HyperbolicBlobs",
            "HyperbolicBlattHierarchy",
            "Simplex",
            "GaussianManifold",
            "TwoMoons",
            "BlattHierarchy",
            "BlattThreeCluster",
        ];

        public static GeneratorParamSchema? ForGenerator(string? generatorName) =>
            generatorName switch
            {
                "CrescentAndEllipsoid" => CrescentAndEllipsoidSchema,
                "MobiusAndEllipsoid" => MobiusAndEllipsoidSchema,
                "HyperbolicBlobs" => HyperbolicBlobsSchema,
                "HyperbolicBlattHierarchy" => HyperbolicBlattHierarchySchema,
                "Simplex" => SimplexSchema,
                "GaussianManifold" => GaussianManifoldSchema,
                "TwoMoons" => TwoMoonsSchema,
                "BlattHierarchy" => BlattHierarchySchema,
                "BlattThreeCluster" => BlattThreeClusterSchema,
                _ => null,
            };

        private static readonly ParamSection SharedSection = new()
        {
            Label = "Shared",
            Params =
            [
                new() { Key = "seed",  Label = "seed",  Type = "int", Min = 0, Max = 99999 },
                new() { Key = "knnK",  Label = "KNN k", Type = "int", Min = 1, Max = 30    },
            ],
        };

        private static readonly ParamSection GraphSection = new()
