    {
        Features = features;
        N = n;
        D = d;
        Label = label;
    }
}

public interface INamedLayer
{
    string Id { get; }
    string Name { get; }
}

internal static class LayerIdentity
{
    public static string Resolve(string? id, string name) =>
        string.IsNullOrWhiteSpace(id) ? name : id;
}

